Title: the default foreign key is not overwritten with the foreignKey option
Description: 
## What are you doing?
creating association between two model classes: Product and ProductPhoto[One product can have many photos]
where product_id from Product table should be foreign key in ProductPhoto table.


```js
Product Model :
var product = sequelize.define('product', {
    product_id:{
        allowNull: false,
        type:DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement:true,
    },
    productName: {
      type:DataTypes.STRING,
      field:'product_name'
    }
, {
    underscored: true,
    freezeTableName: true
  });
  product.associate = function(models) {
  product.hasMany(models.productPhoto,{foriegnKey:'product_id'});
   }
}
ProductPhoto Model:
var productPhoto = sequelize.define('productPhoto', {
  	 productPhotoId:{
        allowNull: false,
        type:DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement:true,
        field:'product_photo_id'
      },
    productPhotoPath: {
      type:DataTypes.STRING,
      field:'product_photo_path'
    }
}
productPhoto.associate = function(models) {
    productPhoto.belongsTo(models.product, {foreignKey: 'product_id'});

  }
```

## What do you expect to happen?
When i execute sync to create database tables ,name product and productPhoto, the foreign key with name product_id in table productPhoto should be created.

